import{z as r,x as i,o as e,c as s,q as t,j as A,D as a,d as B,s as o,S as n}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"长输出的流式稳定","description":"","frontmatter":{"title":"长输出的流式稳定","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/lc-longoutput-streaming.md","filePath":"llm/lc-longoutput-streaming.md","lastUpdated":1791063341000}'),p={name:"llm/lc-longoutput-streaming.md"};function D(d,E,h,m,C,c){const l=i("Mermaid");return e(),s("div",null,[E[2]||(E[2]=t('<h1 id="长输出的流式稳定" tabindex="-1">长输出的流式稳定 <a class="header-anchor" href="#长输出的流式稳定" aria-label="Permalink to &quot;长输出的流式稳定&quot;">​</a></h1><div class="epigraph"><p>长输入把代价付在门口一次，长输出把代价摊进每一步；流式的稳定不是不掉，而是掉的时候客户端知道发生了什么。</p><footer>—— 据 Pope et al., 2022 的带宽账与开放 API 流式结束语义的通行约定整理</footer></div><p><a href="/llm/lc-extrapolation-serving">上一课</a>把窗口声明变成契约。输入侧的账在「显存与调度」单元记完；本课转输出侧：长思维链、长代码这些上万 token 的输出，把 KV 的增长搬进了生成段。<a href="/llm/long-context-memory-curve">显存曲线课</a>警告过「思维链比长文档更易撞墙」；本课把这句警告落成流式服务的三条语义——分位数承诺、中途降级的可见性、断流续传。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>长输出的痛是复利的。输入的 TTFT 只付一次；输出的 KV 每步增长，每步的带宽账随已生成长度线性涨，且生成段没有公共前缀可摊——<a href="/llm/kv-longcontext-budget">预算课</a>那句「生成段各付各的」，在 16K 输出处变成 2 GiB 的常驻与逐拍加深的扫描。更麻烦的是语义。上万步里哪怕单步 0.1% 的抖动概率，期望也有十几次 stall，均值 TPOT 完全掩盖；KV 触顶时的驱逐或降档发生在流中段，已生成文本与后续文本不同质；连接断开时，已提交的几千 token 要么能续、要么重付。只把输出建模成「一串 token 流」，这些事件全部无处安放——客户端把降质当模型变笨，把断流当服务死亡。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三条流式语义。分位数承诺：长输出按 p95/p99 的<a href="/llm/tpot-itl">交错延迟</a>验收而不是均值——步数多到尾部事件必然发生，契约要写「抖几次、抖多深」，而不是「平均多快」。降级可见性：驱逐、量化降档、外推超档这类中段事件写进响应元数据（降级点、降级类型），finish_reason 在<a href="/llm/stop-sequences">停止语义</a>的 finish、eos、length 之外标注服务侧事件源——「流还在继续」与「还在同一配置上生成」是两个命题。续传：把已生成前缀写成可复用的会话前缀，重连等于一次<a href="/llm/kv-prefix-cache">前缀缓存</a>命中，从提交点续流；未提交的挂起尾部按流式挂起规则处理，不重复、不丢失。</p>',7)),(e(),A(n,null,{default:a(()=>[o(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20STEP%5B%22%E8%A7%A3%E7%A0%81%E6%AD%A5%EF%BC%9AKV%20%E8%BF%BD%E5%8A%A0%E3%80%81%E6%89%AB%E6%8F%8F%E9%9A%8F%E9%95%BF%E5%BA%A6%E6%B6%A8%22%5D%20--%3E%20CHK%7B%22%E6%B1%A0%E6%B0%B4%E4%BD%8D%E8%A7%A6%E9%A1%B6%3F%22%7D%0A%20%20CHK%20--%3E%7C%E5%90%A6%7C%20EMIT%5B%22%E6%8F%90%E4%BA%A4%E5%A2%9E%E9%87%8F%E7%BB%99%E5%AE%A2%E6%88%B7%E7%AB%AF%22%5D%0A%20%20CHK%20--%3E%7C%E6%98%AF%7C%20DEG%5B%22%E9%A9%B1%E9%80%90%20%2F%20%E9%99%8D%E6%A1%A3%EF%BC%9A%E6%9C%8D%E5%8A%A1%E4%BE%A7%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20DEG%20--%3E%20META%5B%22%E5%85%83%E6%95%B0%E6%8D%AE%E6%A0%87%E6%B3%A8%E9%99%8D%E7%BA%A7%E7%82%B9%E4%B8%8E%E7%B1%BB%E5%9E%8B%22%5D%0A%20%20META%20--%3E%20EMIT%0A%20%20EMIT%20--%3E%20DONE%7B%22%E7%BB%93%E6%9D%9F%E6%9D%A1%E4%BB%B6%3F%22%7D%0A%20%20DONE%20--%3E%7C%E5%90%A6%7C%20STEP%0A%20%20DONE%20--%3E%7C%E6%98%AF%7C%20FIN%5B%22finish_reason%EF%BC%9A%E5%AE%8C%E6%88%90%20%2F%20%E6%88%AA%E6%96%AD%20%2F%20%E9%99%8D%E7%BA%A7%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>长输出的降级为什么必须显式：生成是自回归的，中段驱逐或换精度改变的是后续所有 token 的条件分布——体验上「还流着」，统计上已经换了模型。显式标注把不可见的质量断裂变成可观测的事件流，客户端才有机会重试、降级或提示用户。投机解码把预算再复杂化一层：草稿 KV 有自己的峰值，接受长度随机（<a href="/llm/acceptance-length-sched">接受长度调度</a>），预算要按接受长度的方差留回滚余量——<a href="/llm/kv-longcontext-budget">预算课</a>边界里那句「投机放大长度方差」，在长输出上是常态而非例外。</p><p><span class="marginnote">16K 输出在 8B FP16 模型上自带 2 GiB KV（每 token 128 KiB），生成段逐拍上涨；单步 0.1% 的 stall 概率在一万六千步里期望 16 次抖动——按均值承诺 TPOT 的服务，在长输出上几乎必然违约。</span></p><p>三条语义里，续传最容易被误解成「重新开始」；把它单独画出来，回答的问题是：断流之后，已提交的几千 token 如何不重付一遍。</p>',4)),(e(),A(n,null,{default:a(()=>[o(l,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20CUT%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E8%BF%9E%E6%8E%A5%E6%96%AD%E5%BC%80%22%5D%20--%3E%20Q%7B%22%E6%96%AD%E7%82%B9%E5%89%8D%E5%86%85%E5%AE%B9%E5%B7%B2%E6%8F%90%E4%BA%A4%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%EF%BC%8C%E5%B7%B2%E7%94%9F%E6%88%90%E5%89%8D%E7%BC%80%22%7C%20CACHE%5B%22%E9%87%8D%E8%BF%9E%20%3D%20%E5%89%8D%E7%BC%80%E7%BC%93%E5%AD%98%E5%91%BD%E4%B8%AD%22%5D%0A%20%20CACHE%20--%3E%20RESUME%5B%22%E4%BB%8E%E6%8F%90%E4%BA%A4%E7%82%B9%E7%BB%AD%E6%B5%81%EF%BC%8C%E4%B8%8D%E9%87%8D%E7%AE%97%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%EF%BC%8C%E5%B0%BE%E9%83%A8%E8%BF%98%E5%9C%A8%E6%8C%82%E8%B5%B7%22%7C%20HOLD%5B%22%E6%8C%89%E6%B5%81%E5%BC%8F%E6%8C%82%E8%B5%B7%E8%A7%84%E5%88%99%E4%BF%9D%E7%95%99%22%5D%0A%20%20HOLD%20--%3E%20RESUME%0A%20%20RESUME%20--%3E%20META%5B%22%E9%99%8D%E7%BA%A7%E5%85%83%E6%95%B0%E6%8D%AE%E9%9A%8F%E6%B5%81%E8%A1%A5%E9%BD%90%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p><span class="marginnote">术语翻译：「自回归」就是每个新 token 都以它前面所有 token 为条件来抽样的生成方式。所以中段一旦驱逐或换精度，坏掉的不是某一个 token，而是它之后所有 token 的「抽签规则」——这正是文中「统计上已经换了模型」的意思。</span></p><p><span class="marginnote">常见误区：初学者容易把断流当「服务挂了」而整单重试——对上万 token 的输出，重试意味着重付整段预填充加整段生成。正确的姿势是把已提交前缀当会话前缀缓存住，让重连退化成一次缓存命中，只补挂起的尾部。</span></p><p>长输出的质量衰减——重复、跑题、退化——是解码与模型问题，本课只负责把它可观测，不负责修。续传语义不覆盖实例崩溃后的跨机 KV 迁移：同副本续走缓存命中，跨副本要重算或搬 KV，归<a href="/llm/lc-context-cache-tiers">分层与放置</a>管。思考型输出的双通道流式（推理流与答案流分离）是产品协议，不改变本课的预算与降级语义——两个通道共用同一条生成段的账。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>长输出把 KV 增长搬进生成段：无共享可摊、带宽逐拍加深，预算按输出长度方差留余量。</li><li>流式承诺按分位数写：p95/p99 交错延迟是长输出的主指标，均值掩盖必然发生的尾部。</li><li>中段降级必须显式：元数据标注降级点与类型，finish_reason 增加服务侧事件源。</li><li>续传 = 已提交前缀的缓存命中 + 未提交尾部的流式挂起，不重复不丢失。</li><li>出处：Pope et al., 2022；Leviathan et al., ICML 2023（投机方差口径）；流式结束语义据开放 API 通行约定。</li></ul>',6))])}const F=r(p,[["render",D]]);export{T as __pageData,F as default};
